from typing import List


def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    """Count length-m lowercase strings by their LCS length with s."""
    mod = 998244353
    masks = {}
    for i, char in enumerate(s):
        masks[char] = masks.get(char, 0) | (1 << i)
    letters = list(masks.values())
    absent = 26 - len(letters)
    size = 1 << n
    transitions = []
    for state in range(size):
        row = []
        for match in letters:
            x = state | match
            row.append(x & ~(x - ((state << 1) | 1)))
        transitions.append(row)
    dp = [0] * size
    dp[0] = 1
    for _ in range(m):
        nxt = [value * absent % mod for value in dp]
        for state, value in enumerate(dp):
            if value:
                for target in transitions[state]:
                    nxt[target] = (nxt[target] + value) % mod
        dp = nxt
    answer = [0] * (n + 1)
    for state, value in enumerate(dp):
        k = state.bit_count()
        answer[k] = (answer[k] + value) % mod
    return answer

