from typing import List


def max_product_subsequence(nums: List[int], k: int, limit: int) -> int:
    """Maximize a nonempty subsequence product with alternating sum k."""
    offset = sum(nums)
    if abs(k) > offset:
        return -1
    cap = limit + 1
    even = [0] * (cap + 1)
    odd = [0] * (cap + 1)
    for value in nums:
        new_even = even[:]
        new_odd = odd[:]
        for product in range(cap + 1):
            target = min(cap, product * value)
            if even[product]:
                new_odd[target] |= even[product] << value
            if odd[product]:
                new_even[target] |= odd[product] >> value
        new_odd[min(cap, value)] |= 1 << (offset + value)
        even, odd = new_even, new_odd
    target_bit = 1 << (offset + k)
    for product in range(limit, -1, -1):
        if (even[product] | odd[product]) & target_bit:
            return product
    return -1

